import os
from typing import Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


class DeadLetterPublisher:
    def __init__(
        self,
        queue_url: str,
        dead_letter_queue_url: str,
        region_name: Optional[str] = None,
    ) -> None:
        self.queue_url = queue_url
        self.dead_letter_queue_url = dead_letter_queue_url
        self.sqs = boto3.client("sqs", region_name=region_name)

    def _send_to_dead_letter(self, message_body: str, original_message_id: Optional[str] = None) -> None:
        attributes = {}
        if original_message_id:
            attributes["OriginalMessageId"] = {
                "StringValue": original_message_id,
                "DataType": "String",
            }

        self.sqs.send_message(
            QueueUrl=self.dead_letter_queue_url,
            MessageBody=message_body,
            MessageAttributes=attributes,
        )

    def process_messages(self) -> None:
        while True:
            response = self.sqs.receive_message(
                QueueUrl=self.queue_url,
                MaxNumberOfMessages=10,
                WaitTimeSeconds=20,
                MessageAttributeNames=["All"],
                AttributeNames=["All"],
            )

            messages = response.get("Messages", [])
            if not messages:
                continue

            for message in messages:
                receipt_handle = message["ReceiptHandle"]
                body = message.get("Body", "")
                message_id = message.get("MessageId")

                try:
                    self._process_message(body)
                    self.sqs.delete_message(
                        QueueUrl=self.queue_url,
                        ReceiptHandle=receipt_handle,
                    )
                except Exception:
                    try:
                        self._send_to_dead_letter(body, original_message_id=message_id)
                    finally:
                        self.sqs.delete_message(
                            QueueUrl=self.queue_url,
                            ReceiptHandle=receipt_handle,
                        )

    def _process_message(self, body: str) -> None:
        raise NotImplementedError("Implement message processing logic here.")


def main() -> None:
    queue_url = os.environ["AWS_SQS_QUEUE_URL"]
    dead_letter_queue_url = os.environ["AWS_SQS_DEAD_LETTER_QUEUE_URL"]
    region_name = os.getenv("AWS_REGION")

    publisher = DeadLetterPublisher(
        queue_url=queue_url,
        dead_letter_queue_url=dead_letter_queue_url,
        region_name=region_name,
    )
    publisher.process_messages()


if __name__ == "__main__":
    try:
        main()
    except (KeyError, BotoCoreError, ClientError) as exc:
        raise SystemExit(f"Failed to run dead-letter publisher: {exc}")
